/** Outcome evaluator for precomputed binary hypothesis observations.
 * This module never reads lottery data. Inputs must be generated by a frozen,
 * chronological walk-forward procedure; each row pairs candidate and baseline.
 */
export type EvaluationPhase = "discovery"|"validation"|"holdout"|"prospective";
export interface Observation {
  drawId:number;
  phase:EvaluationPhase;
  hit:boolean;
  baselineHit:boolean;
  period?:string;
}
export interface RateSummary { n:number; hits:number; rate:number; wilson95:[number,number]; }
export interface PeriodSummary extends RateSummary { period:string; baseline:RateSummary; difference:number; }
export type EvaluationDecision = "insufficient-data"|"no-evidence"|"continue-research"|"holdout-confirmed"|"prospective-replicated";
export interface HypothesisEvaluation {
  phase:EvaluationPhase;
  candidate:RateSummary;
  baseline:RateSummary;
  difference:number;
  pairedDifferenceCI95:[number,number];
  discordantCandidateWins:number;
  discordantBaselineWins:number;
  exactMcNemarP:number;
  adjustedP:number;
  adjustedAlpha:number;
  periodSummaries:PeriodSummary[];
  positivePeriods:number;
  periodsWithData:number;
  decision:EvaluationDecision;
  warnings:string[];
}
export interface EvaluatorOptions { testCount?:number; alpha?:number; minimumN?:number; }
function wilson(hits:number,n:number,z=1.96):[number,number]{
 if(n<=0||hits<0||hits>n)return [0,1];
 const p=hits/n,z2=z*z,den=1+z2/n,center=(p+z2/(2*n))/den,half=z*Math.sqrt((p*(1-p)+z2/(4*n))/n)/den;
 return [Math.max(0,center-half),Math.min(1,center+half)];
}
function summary(hits:number,n:number):RateSummary{return {n,hits,rate:n?hits/n:0,wilson95:wilson(hits,n)};}
function binomPmf(k:number,n:number,p=.5):number{
 if(n===0)return 1;
 let log=0;for(let i=1;i<=k;i++)log+=Math.log(n-i+1)-Math.log(i);
 return Math.exp(log+k*Math.log(p)+(n-k)*Math.log(1-p));
}
/** Exact two-sided McNemar p-value, conditional on discordant paired outcomes. */
function exactMcNemar(a:number,b:number):number{
 const n=a+b;if(!n)return 1;const observed=binomPmf(Math.min(a,b),n);
 let total=0;for(let k=0;k<=n;k++)if(binomPmf(k,n)<=observed+1e-12)total+=binomPmf(k,n);
 return Math.min(1,total);
}
function pairedDiffCI(wins:number,losses:number,n:number):[number,number]{
 if(!n)return [-1,1];const d=(wins-losses)/n,variance=Math.max(0,(wins+losses)/n-d*d);
 const half=1.96*Math.sqrt(variance/n);return [Math.max(-1,d-half),Math.min(1,d+half)];
}
function summarizePeriods(rows:Observation[]):PeriodSummary[]{
 const groups=new Map<string,Observation[]>();for(const r of rows){const label=r.period??"unspecified";const g=groups.get(label)||[];g.push(r);groups.set(label,g);}
 return [...groups.entries()].sort(([a],[b])=>a.localeCompare(b)).map(([period,g])=>{
  const h=g.filter(x=>x.hit).length,bh=g.filter(x=>x.baselineHit).length;
  const candidate=summary(h,g.length),baseline=summary(bh,g.length);
  return {...candidate,period,baseline,difference:candidate.rate-baseline.rate};
 });
}
export function evaluateHypothesis(rows:Observation[],phase:EvaluationPhase,options:EvaluatorOptions={}):HypothesisEvaluation{
 const warnings:string[]=[];
 const ordered=rows.filter(r=>r.phase===phase).sort((a,b)=>a.drawId-b.drawId);
 for(let i=1;i<ordered.length;i++)if(ordered[i].drawId===ordered[i-1].drawId)warnings.push("Duplicate drawId within phase; duplicate rows can inflate evidence.");
 const n=ordered.length,h=ordered.filter(r=>r.hit).length,bh=ordered.filter(r=>r.baselineHit).length;
 const wins=ordered.filter(r=>r.hit&&!r.baselineHit).length,losses=ordered.filter(r=>!r.hit&&r.baselineHit).length;
 const candidate=summary(h,n),baseline=summary(bh,n),difference=candidate.rate-baseline.rate;
 const alpha=options.alpha??.05,testCount=Math.max(1,Math.floor(options.testCount??1)),adjustedAlpha=alpha/testCount;
 const rawP=exactMcNemar(wins,losses),adjustedP=Math.min(1,rawP*testCount);
 const periods=summarizePeriods(ordered),positivePeriods=periods.filter(p=>p.difference>0).length;
 const pairedCI=pairedDiffCI(wins,losses,n),minimumN=Math.max(1,Math.floor(options.minimumN??100));
 let decision:EvaluationDecision="insufficient-data";
 if(phase==="discovery"){
  decision="insufficient-data";
 } else if(n>=minimumN){
  if(phase==="validation"&&difference>0&&pairedCI[0]>0&&adjustedP<=adjustedAlpha)decision="continue-research";
  else if(phase==="holdout"&&difference>0&&pairedCI[0]>0&&adjustedP<=adjustedAlpha)decision="holdout-confirmed";
  else if(phase==="prospective"&&difference>0&&pairedCI[0]>0&&adjustedP<=adjustedAlpha)decision="prospective-replicated";
  else decision="no-evidence";
 }
 if(n<minimumN)warnings.push("Sample below minimumN="+minimumN+"; decision remains insufficient-data.");
 if(phase==="discovery")warnings.push("Discovery phase is descriptive only; it cannot confirm or promote a hypothesis.");
 if(testCount>1)warnings.push("Bonferroni adjustment applied across "+testCount+" planned tests; testCount must be frozen before evaluation.");
 warnings.push("Paired baseline comparison is required: candidate and baseline evaluated on the same draws.");
 warnings.push("Holdout/prospective decisions are meaningful only if those phases were untouched during candidate selection.");
 return {phase,candidate,baseline,difference,pairedDifferenceCI95:pairedCI,discordantCandidateWins:wins,discordantBaselineWins:losses,exactMcNemarP:rawP,adjustedP,adjustedAlpha,periodSummaries:periods,positivePeriods,periodsWithData:periods.length,decision,warnings};
}
